//! The perturbation terms of the Barker-Henderson theory against the exact-source library.
//! Generated by tools/rust_port/validate_ais_ljs.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::ljs::{ais_ljs_ex, chi_ljs_ex};

const ATOL: f64 = 1.0e-15;
const RTOL: f64 = 1.0e-13;

#[test]
fn the_terms_match_the_source() {
    let mut rows = include_str!("fixtures/ais_ljs.csv").lines();
    let header = rows.next().expect("the header of the fixture");
    assert_eq!(header, "case;term;chi");
    let mut compared = 0;
    for row in rows {
        let fields: Vec<&str> = row.split(';').collect();
        assert_eq!(fields.len(), 3, "row {row}");
        let case: Vec<&str> = fields[0].split('|').collect();
        assert_eq!(case.len(), 3, "case {row}");
        let index: usize = case[0].parse().expect("the index of the term");
        let reduced_distance: f64 = case[1].parse().expect("the reduced distance");
        let reduced_density: f64 = case[2].parse().expect("the reduced density");
        let source_term: f64 = fields[1].parse().expect("the source term");
        let source_correction: f64 = fields[2].parse().expect("the source correction");

        let term = ais_ljs_ex(index, reduced_distance, reduced_density).expect("the term");
        let correction = chi_ljs_ex(reduced_distance, reduced_density).expect("the correction");
        assert!(
            (source_term - term).abs() <= ATOL + RTOL * source_term.abs(),
            "the term of the case {row}: source {source_term} native {term}"
        );
        assert!(
            (source_correction - correction).abs() <= ATOL + RTOL * source_correction.abs(),
            "the correction of the case {row}: source {source_correction} native {correction}"
        );
        compared += 1;
    }
    assert!(compared > 0, "the fixture holds no case");
}

#[test]
fn the_first_and_the_second_term_carry_the_density_factor() {
    // The first and the second term are divided by the reduced density while
    // the third term and the correction are not.
    let reduced_distance = 1.1;
    let reduced_density = 0.8;
    let first = ais_ljs_ex(1, reduced_distance, reduced_density).expect("the first term");
    let second = ais_ljs_ex(2, reduced_distance, reduced_density).expect("the second term");
    let third = ais_ljs_ex(3, reduced_distance, reduced_density).expect("the third term");
    let correction = chi_ljs_ex(reduced_distance, reduced_density).expect("the correction");
    assert!(first.is_finite());
    assert!(second.is_finite());
    assert!(third.is_finite());
    assert!(correction.is_finite());
    // The correction of the second order term is the fourth term of the source.
    let fourth = ais_ljs_ex(4, reduced_distance, reduced_density).expect("the fourth term");
    assert!((fourth - correction).abs() <= ATOL + RTOL * correction.abs());
}

#[test]
fn a_non_positive_input_is_rejected() {
    assert!(ais_ljs_ex(1, 0.0, 1.0).is_err());
    assert!(ais_ljs_ex(1, 1.0, -0.5).is_err());
    assert!(chi_ljs_ex(-1.0, 1.0).is_err());
    assert!(chi_ljs_ex(1.0, 0.0).is_err());
}
